{
	"@context": "https://schema.org",
	"@type": "TechArticle",
	"headline": "CSS Multi-Step Form, No JavaScript | Pure CSS",
	"description": "Radio inputs control which step panel is visible, with no JavaScript and no page reload.",
	"url": "https://purecss.com/examples/multi-step-form/",
	"author": {
		"@type": "Person",
		"name": "Adam Culpepper",
		"url": "https://x.com/adamculpepper"
	},
	"publisher": {
		"@type": "Organization",
		"name": "Pure CSS",
		"url": "https://purecss.com"
	},
	"datePublished": "2026-05-22","dateModified": "2026-08-29"
}

{
	"@context": "https://schema.org",
	"@type": "FAQPage",
	"mainEntity": [{
		"@type": "Question",
		"name": "Does a CSS multi step form actually submit?",
		"acceptedAnswer": { "@type": "Answer", "text": "Yes, as one form. The panels are only visual, so every field in every step is part of the same submission whether or not the reader can see it at the time. Put the `` around the wrapper and give each input a `name`." }
	},{
		"@type": "Question",
		"name": "Can I validate each step before moving on?",
		"acceptedAnswer": { "@type": "Answer", "text": "Not with CSS alone. `form:has(:invalid)` can gray out the Next button in the same way described on input validation, but it cannot stop the label from switching the radio, because a label click is not something a stylesheet can cancel. Real per step gating needs script." }
	},{
		"@type": "Question",
		"name": "Why will my step panels not animate?",
		"acceptedAnswer": { "@type": "Answer", "text": "Because `display` cannot be transitioned. The property has no intermediate values for the browser to interpolate. Lay every panel out side by side in a track and move the track with `transform: translateX()` instead, which is what the sliding variant on this page does." }
	},{
		"@type": "Question",
		"name": "How do I remember which step someone was on?",
		"acceptedAnswer": { "@type": "Answer", "text": "You cannot, in CSS. The state lives in the DOM and resets on every page load to whichever radio has the `checked` attribute. Persisting it means storing the step and restoring it with script, or giving each step its own URL." }
	},{
		"@type": "Question",
		"name": "Is a multi step form better than one long form?",
		"acceptedAnswer": { "@type": "Answer", "text": "It depends on the form. Splitting reduces how much a reader sees at once, which helps on a phone and on anything over about ten fields. It also hides the total length, which some people find worse rather than better, so keep the progress indicator visible." }
	}]
}

