// you know JavaScript is required for copying code
// Two snippets side by side should end on the same line, at the height of
// the SHORTER one, so the longer scrolls instead of leaving the other half
// empty. CSS cannot express that: a grid row always grows to its tallest
// child, never its shortest. The CSS fallback matches them to the taller,
// and this trims the pair down to the shorter.
const matchCodeHeights = () => {
	document.querySelectorAll('.code-section').forEach(section => {
		const panes = [...section.querySelectorAll('pre[class*="language-"]')];
		if (panes.length !== 2) return;
		panes.forEach(p => { p.style.height = ''; });
		if (!section.offsetParent && section.offsetHeight === 0) return;
		// stacked rather than side by side, so leave them alone
		if (Math.abs(panes[0].getBoundingClientRect().top - panes[1].getBoundingClientRect().top) > 4) return;
		const shortest = Math.min(...panes.map(p => p.scrollHeight));
		// a floor, so three lines of markup cannot crush a long stylesheet,
		// and the same ceiling the stylesheet already applies
		const h = Math.min(Math.max(shortest, 200), 448);
		panes.forEach(p => { p.style.height = h + 'px'; });
	});
};
matchCodeHeights();
window.addEventListener('resize', () => {
	clearTimeout(window.__codeFit);
	window.__codeFit = setTimeout(matchCodeHeights, 150);
});

document.querySelectorAll('.copy-btn').forEach(btn => {
	btn.addEventListener('click', () => {
		const pre = btn.nextElementSibling;
		navigator.clipboard.writeText(pre.textContent.trimEnd()).then(() => {
			btn.classList.add('copied');
			setTimeout(() => btn.classList.remove('copied'), 1500);
		});
	});
});
